<?php
/**
 * Standard build (block editor) support.
 *
 *   POST /wp-json/bizink/v1/blocks/install-theme  { "activate": true, "style": "theme-03-ledger" }   (administrator)
 *
 * Installs Twenty Twenty-Five if it's missing, copies the Bizink Blocks child theme that ships with this plugin
 * (block-theme/bizink-blocks, generated by tools/build_block_theme.py from the Bizink theme files) into
 * wp-content/themes, and optionally activates it with one of its style variations (theme-01 … theme-06).
 * Re-running updates the theme files to this plugin version's copy.
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'bizink/v1',
			'/blocks/install-theme',
			array(
				'methods'             => 'POST',
				'permission_callback' => function () {
					return current_user_can( 'install_themes' ) && current_user_can( 'switch_themes' );
				},
				'callback'            => 'bz_core_blocks_install_theme',
			)
		);
	}
);

add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'bizink/v1',
			'/blocks/finish',
			array(
				'methods'             => 'POST',
				'permission_callback' => function () {
					return current_user_can( 'manage_options' ) && current_user_can( 'activate_plugins' );
				},
				'callback'            => 'bz_core_blocks_finish',
			)
		);
	}
);

/* A classic menu (by name) as navigation block markup. */
function bz_core_blocks_menu_markup( $name ) {
	$menu = wp_get_nav_menu_object( $name );
	if ( ! $menu ) {
		return '';
	}
	$items = wp_get_nav_menu_items( $menu->term_id, array( 'post_status' => 'publish' ) );
	$by    = array();
	foreach ( (array) $items as $it ) {
		$by[ (int) $it->menu_item_parent ][] = $it;
	}
	$markup = function ( $parent ) use ( &$markup, $by ) {
		$out = '';
		foreach ( isset( $by[ $parent ] ) ? $by[ $parent ] : array() as $it ) {
			$attrs = wp_json_encode( array( 'label' => wp_strip_all_tags( $it->title ), 'url' => $it->url ? $it->url : '#', 'kind' => 'custom', 'isTopLevelLink' => true ) );
			$out  .= isset( $by[ $it->ID ] )
				? '<!-- wp:navigation-submenu ' . $attrs . ' -->' . $markup( $it->ID ) . '<!-- /wp:navigation-submenu -->'
				: '<!-- wp:navigation-link ' . $attrs . ' /-->';
		}
		return $out;
	};
	return $markup( 0 );
}

/* A wp_navigation post (created or updated by title) holding $markup. */
function bz_core_blocks_navigation( $title, $markup ) {
	$args = array( 'post_type' => 'wp_navigation', 'post_status' => 'publish', 'post_title' => $title, 'post_content' => wp_slash( $markup ) );
	$prev = get_posts( array( 'post_type' => 'wp_navigation', 'title' => $title, 'post_status' => 'publish', 'numberposts' => 1, 'fields' => 'ids' ) );
	return $prev ? wp_update_post( array_merge( $args, array( 'ID' => $prev[0] ) ) ) : wp_insert_post( $args );
}

/**
 * Finish a Standard build: header (logo, Main Menu, Book a call) and footer (live Client Details fields through
 * shortcodes, Footer Services and Footer Legal menus, compliance note) as Bizink Blocks template parts, then
 * Elementor and Elementor Pro off. bizink-core and Gravity Forms stay.
 */
function bz_core_blocks_finish( WP_REST_Request $r ) {
	if ( 'bizink-blocks' !== get_stylesheet() ) {
		return new WP_Error( 'bz_blocks_theme', 'Activate the Bizink Blocks theme first (blocks/install-theme).', array( 'status' => 409 ) );
	}
	$log  = array();
	$main = bz_core_blocks_navigation( 'Main menu', bz_core_blocks_menu_markup( 'Main Menu' ) );
	$svc  = bz_core_blocks_navigation( 'Footer services', bz_core_blocks_menu_markup( 'Footer Services' ) );
	$leg  = bz_core_blocks_navigation( 'Footer legal', bz_core_blocks_menu_markup( 'Footer Legal' ) );
	$pad  = '"style":{"spacing":{"padding":{"top":"var:preset|spacing|30","bottom":"var:preset|spacing|30"}}}';
	$header = '<!-- wp:group {"align":"full",' . $pad . ',"layout":{"type":"constrained"}} --><div class="wp-block-group alignfull" style="padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)">'
		. '<!-- wp:group {"align":"wide","layout":{"type":"flex","justifyContent":"space-between","flexWrap":"wrap"}} --><div class="wp-block-group alignwide">'
		. '<!-- wp:site-logo {"width":170} /-->'
		. '<!-- wp:group {"layout":{"type":"flex","flexWrap":"wrap"}} --><div class="wp-block-group">'
		. '<!-- wp:navigation {"ref":' . (int) $main . ',"overlayBackgroundColor":"base","overlayTextColor":"contrast","layout":{"type":"flex","justifyContent":"right"}} /-->'
		. '<!-- wp:shortcode -->[bz_book_button]<!-- /wp:shortcode -->'
		. '</div><!-- /wp:group --></div><!-- /wp:group --></div><!-- /wp:group -->';
	$col = function ( $inner ) {
		return '<!-- wp:column --><div class="wp-block-column">' . $inner . '</div><!-- /wp:column -->';
	};
	$footer = '<!-- wp:group {"align":"full","backgroundColor":"accent-2","textColor":"base","style":{"spacing":{"padding":{"top":"var:preset|spacing|50","bottom":"var:preset|spacing|40"}},"elements":{"link":{"color":{"text":"var:preset|color|base"}}}},"layout":{"type":"constrained"}} -->'
		. '<div class="wp-block-group alignfull has-base-color has-accent-2-background-color has-text-color has-background has-link-color" style="padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--40)">'
		. '<!-- wp:columns {"align":"wide"} --><div class="wp-block-columns alignwide">'
		. $col( '<!-- wp:paragraph --><p><strong>[bz field=firm_name]</strong></p><!-- /wp:paragraph --><!-- wp:paragraph --><p>[bz field=footer_blurb]</p><!-- /wp:paragraph --><!-- wp:paragraph --><p>[bz field=address_full]</p><!-- /wp:paragraph -->' )
		. $col( '<!-- wp:heading {"level":4} --><h4 class="wp-block-heading">Services</h4><!-- /wp:heading --><!-- wp:navigation {"ref":' . (int) $svc . ',"overlayMenu":"never","layout":{"type":"flex","orientation":"vertical"}} /-->' )
		. $col( '<!-- wp:heading {"level":4} --><h4 class="wp-block-heading">Contact</h4><!-- /wp:heading --><!-- wp:paragraph --><p><a href="[bz field=phone_href]">[bz field=phone]</a><br><a href="[bz field=email_href]">[bz field=email]</a><br>[bz field=hours]</p><!-- /wp:paragraph -->' )
		. '</div><!-- /wp:columns -->'
		. '<!-- wp:separator {"align":"wide","backgroundColor":"base"} --><hr class="wp-block-separator alignwide has-text-color has-base-color has-alpha-channel-opacity has-base-background-color has-background"/><!-- /wp:separator -->'
		. '<!-- wp:group {"align":"wide","layout":{"type":"flex","justifyContent":"space-between","flexWrap":"wrap"}} --><div class="wp-block-group alignwide">'
		. '<!-- wp:paragraph {"fontSize":"small"} --><p class="has-small-font-size">[bz field=copyright]<br>Built with Aukume by <a href="https://bizinkonline.com" target="_blank" rel="noopener">Bizink</a> [bz_cookie_settings]</p><!-- /wp:paragraph -->'
		. '<!-- wp:navigation {"ref":' . (int) $leg . ',"overlayMenu":"never","fontSize":"small"} /-->'
		. '</div><!-- /wp:group -->'
		. '<!-- wp:paragraph {"fontSize":"small"} --><p class="has-small-font-size">[bz field=compliance_note]</p><!-- /wp:paragraph -->'
		. '</div><!-- /wp:group -->';
	if ( function_exists( 'bz_core_handover_template_part' ) ) {
		bz_core_handover_template_part( 'header', 'Header', 'header', $header );
		bz_core_handover_template_part( 'footer', 'Footer', 'footer', $footer );
		$log[] = 'Header and footer written.';
	}
	require_once ABSPATH . 'wp-admin/includes/plugin.php';
	$off = array_values( array_filter( get_option( 'active_plugins', array() ), function ( $f ) {
		return (bool) preg_match( '#^(elementor-pro|elementor)/#', $f );
	} ) );
	if ( $off ) {
		deactivate_plugins( $off, true );
		$log[] = 'Deactivated: ' . implode( ', ', $off ) . '.';
	}
	return array( 'ok' => true, 'log' => $log );
}

/* The header's "Book a call" button: the Client Details booking URL, else the Book a Call page. */
add_shortcode(
	'bz_book_button',
	function () {
		$url = function_exists( 'bz_core_get' ) ? bz_core_get( 'booking_url' ) : '';
		return '<div class="wp-block-buttons"><div class="wp-block-button"><a class="wp-block-button__link wp-element-button" href="' . esc_url( $url ? $url : home_url( '/book-a-call/' ) ) . '">Book a call</a></div></div>';
	}
);

function bz_core_blocks_install_theme( WP_REST_Request $r ) {
	$log = array();
	require_once ABSPATH . 'wp-admin/includes/file.php';
	require_once ABSPATH . 'wp-admin/includes/theme.php';
	require_once ABSPATH . 'wp-admin/includes/class-wp-upgrader.php';
	if ( ! wp_get_theme( 'twentytwentyfive' )->exists() ) {
		$api = themes_api( 'theme_information', array( 'slug' => 'twentytwentyfive', 'fields' => array( 'sections' => false ) ) );
		if ( is_wp_error( $api ) ) {
			return $api;
		}
		$ok = ( new Theme_Upgrader( new Automatic_Upgrader_Skin() ) )->install( $api->download_link );
		if ( ! $ok || is_wp_error( $ok ) ) {
			return new WP_Error( 'bz_blocks_parent', 'Could not install Twenty Twenty-Five.', array( 'status' => 500 ) );
		}
		$log[] = 'Installed Twenty Twenty-Five.';
	}
	WP_Filesystem();
	global $wp_filesystem;
	$src  = dirname( __DIR__ ) . '/block-theme/bizink-blocks';
	$dest = get_theme_root() . '/bizink-blocks';
	if ( ! is_dir( $src ) ) {
		return new WP_Error( 'bz_blocks_missing', 'This bizink-core has no block theme (block-theme/bizink-blocks).', array( 'status' => 500 ) );
	}
	if ( ! $wp_filesystem->is_dir( $dest ) ) {
		$wp_filesystem->mkdir( $dest );
	}
	$copied = copy_dir( $src, $dest );
	if ( is_wp_error( $copied ) ) {
		return $copied;
	}
	wp_clean_themes_cache();
	$log[] = 'Bizink Blocks theme files updated.';

	$p = (array) $r->get_json_params();
	if ( ! empty( $p['activate'] ) ) {
		switch_theme( 'bizink-blocks' );
		$log[] = 'Bizink Blocks is the active theme.';
	}
	$style = isset( $p['style'] ) ? sanitize_file_name( $p['style'] ) : '';
	if ( $style && 'bizink-blocks' === get_stylesheet() ) {
		$file = $dest . '/styles/' . $style . '.json';
		if ( ! file_exists( $file ) ) {
			return new WP_Error( 'bz_blocks_style', 'Unknown style ' . $style . '.', array( 'status' => 400 ) );
		}
		$variation = json_decode( (string) file_get_contents( $file ), true ); // phpcs:ignore WordPress.WP.AlternativeFunctions
		unset( $variation['$schema'], $variation['title'] );
		$variation['isGlobalStylesUserThemeJSON'] = true;
		$gs_id = WP_Theme_JSON_Resolver::get_user_global_styles_post_id();
		if ( $gs_id ) {
			wp_update_post( array( 'ID' => $gs_id, 'post_content' => wp_slash( wp_json_encode( $variation ) ) ) );
			$log[] = 'Style: ' . $style . '.';
		}
	}
	return array( 'ok' => true, 'log' => $log, 'theme' => get_stylesheet() );
}
